            if (jQuery(fieldElm).hasClass('validate-fullname')) {
                if (validation_rules[fieldElm.name]) {
                    validation_rules[fieldElm.name]['fullname_valid'] = true;
                } else {
                    validation_rules[fieldElm.name] = {fullname_valid: true};
                }
                validation_rules[fieldElm.name]['notnumeric'] = true;
            }

            if (jQuery(fieldElm).hasClass('validate-notnumeric')) {
                if (validation_rules[fieldElm.name]) {
                    validation_rules[fieldElm.name]['notnumeric'] = true;
                } else {
                    validation_rules[fieldElm.name] = {notnumeric: true};
                }
            }

            if (jQuery(fieldElm).hasClass('validate-special')) {
                if (validation_rules[fieldElm.name]) {
                    validation_rules[fieldElm.name]['notspecial'] = true;
                } else {
                    validation_rules[fieldElm.name] = {notspecial: true};
                }
            }

            if (jQuery(fieldElm).hasClass('validate-availability')) {
                let availabilitymsg = jQuery(fieldElm).data('checkmsg') || fieldEmailAvailabilityMsg;
                if (validation_rules[fieldElm.name]) {
