            if (jQuery(fieldElm).hasClass('validate-cc-exp')) {
                if (validation_rules[fieldElm.name]) {
                    validation_rules[fieldElm.name]['validateCcExp'] = true;
                    validation_messages[fieldElm.name]['validateCcExp'] = fieldCcExpMsg;
                } else {
                    validation_rules[fieldElm.name] = {validateCcExp: true};
                    validation_messages[fieldElm.name] = {validateCcExp: fieldCcExpMsg};
                }

            }

            if (jQuery(fieldElm).hasClass('validate-cc-cvn')) {
                if (validation_rules[fieldElm.name]) {
                    validation_rules[fieldElm.name]['validateCcCvn'] = true;
