                        validation_messages[fieldElm.name][lengthType] = fieldLengthMsg;
                    } else {
                        validation_messages[fieldElm.name] = {'maxlength': fieldLengthMsg};
                    }
                }
            }
            if (jQuery(fieldElm).hasClass('validate-length1')) {
                var lengthType = '';
                var lengthVal = '';
                var classesStr = jQuery(fieldElm).attr('class');
                var minstr = 'minimum-length';
                var minstrlen = minstr.length;
                var maxstr = 'maximum-length';
                var maxstrlen = maxstr.length;
                var minindexf = classesStr.search(minstr);
                var maxindexf = classesStr.search(maxstr);

                if (minindexf) {
                    lengthType = 'minlength';
                    lengthVal = classesStr.slice(minindexf + minstrlen, minindexf + minstrlen + 1)
                    if (validation_rules[fieldElm.name]) {
