                    }
                }
                if (maxindexf) {
                    lengthType = 'maxlength';
                    lengthVal = classesStr.slice(maxindexf + maxstrlen, maxindexf + maxstrlen + 1)
                    if (validation_rules[fieldElm.name]) {
                        validation_messages[fieldElm.name][lengthType] = fieldLengthMsg;
                        //                validation_rules[fieldElm.name][lengthType] = true;
                    } else {
                        validation_messages[fieldElm.name] = {'maxlength': fieldLengthMsg};
                        //                validation_rules[fieldElm.name] = {lengthType: true};
                    }
                }
            }


        });
        jQuery(form_id).validate({
            errorClass: 'validation-advice',
            errorElement: 'div',
            highlight: function (element, errorClass, validClass) {
                //jQuery(element).removeClass('validation-advice');
            },
            invalidHandler: function (form, validator) {
                var errors = validator.numberOfInvalids();
                if (errors) {
                    validator.errorList[0].element.focus();
                }
            },
            success: function (error, element) {
                error.remove();
            },
            errorPlacement: function (error, element) {
                if (jQuery('.validation-advice.session-error').length) {
                    jQuery('.validation-advice.session-error').remove();
                }
                if (element.attr("type") == "radio" && element.parent(".radio-bubble")) {
                    error.appendTo(element.parent(".radio-bubble").parent());
                } else if (element.attr("type") == "checkbox" && element.parent(".input-checkbox")) {
                    error.appendTo(element.parent(".input-checkbox"));
                } else {
                    if (element.parent('span').length) {
                        element.parent('span').after(error);
                    } else {
                        element.after(error);
                    }
                }
                if (autohide !== false) {
                    error_timeoutIds[element[0].id] = setTimeout(() => {
                        error.remove();
                    }, autohide * 1000);
                }
            },
            rules: validation_rules,
            messages: validation_messages,
            submitHandler: function (form) {
                if (is_submit) {
                    if (jQuery(form).valid()) {
                        showLoaderImage();
                        form.submit();
                    }
                }
            }
        });
        return;
    }

