    function submit_file_form_ajax(formelm, callback) {
        if (!jQuery(formelm).valid()) {
            return false;
        }
        var formData = new FormData(formelm);
        jQuery.ajax({
            url: jQuery(formelm).attr('action'),
            type: 'POST',
            data: formData,
            cache: false,
            contentType: false,
            processData: false,
            dataType: 'json',
            beforeSend: function () {
                showLoaderImage();
            },
            success: function (resp) {
                if (resp.type == 'success') {
                    if (resp.message) {
                        success_flash_message(resp.message);
                    }
                } else {
                    if (resp.errors) {
                        showErrors(resp.errors);
                    }
                    if (resp.message) {
                        error_flash_message(resp.message);
                    }
                }
                if (callback) {
                    callback(resp);
                }
                if (resp.redirect) {
                    location.href = resp.redirect;
                }

            },
            complete: function (resp) {
                hideLoaderImage();
            }
        });
        return false;
    }

    function submit_form_ajax(formelm, callback) {
        if (!jQuery(formelm).valid()) {
            return false;
        }
        jQuery.ajax({
            url: jQuery(formelm).attr('action'),
            dataType: 'json',
            type: 'POST',
            data: jQuery(formelm).serialize(),
            beforeSend: function () {
                showLoaderImage();
            },
            success: function (resp) {
                if (resp.type == 'success') {
                    if (resp.message) {
                        success_flash_message(resp.message);
                    }
                } else {
                    if (resp.errors) {
                        showErrors(resp.errors, formelm);
                    }
                    if (resp.message) {
                        error_flash_message(resp.message);
                    }
                }
                if (callback) {
                    callback(resp);
                }
                if (resp.redirect) {
                    location.href = resp.redirect;
                }

            },
            complete: function (resp) {
                hideLoaderImage();
            }
        });
        return false;
    }

